CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 ANY UNIQUE, c1 INTEGER COLLATE NOCASE, c2 ANY, c3 INTEGER DEFAULT 'd') STRICT;
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL CHECK(c0 IS NULL OR length(c0) < 40), c1 TEXT, c2 VARCHAR(10) UNIQUE, c3 NUMERIC UNIQUE, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, ref) VALUES(0, 'Lambda', 5, x'c038', 7);
SELECT length('señor'), upper('señor'), lower('señor'), substr('señor', -3, 2), instr('señor', 'Lambda'), replace('señor', 'a', '_'), trim('señor'), ltrim('señor', 'ab'), hex('señor'), quote('señor'), unicode('señor'), 'señor' LIKE 'a%', 'señor' GLOB '?', char(76, 580), 'señor' || 'Lambda', 'señor' < 'Lambda', 'señor' = 'Lambda' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', -3, 0), instr('phi', 'x_y'), replace('phi', 'é', ''), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '%', 'phi' GLOB 'a*', char(80, 251), 'phi' || 'x_y', 'phi' < 'x_y', 'phi' = 'x_y' COLLATE NOCASE;
SELECT length('Ελλάδα'), upper('Ελλάδα'), lower('Ελλάδα'), substr('Ελλάδα', 3, 1), instr('Ελλάδα', 'beta'), replace('Ελλάδα', 'é', 'XY'), trim('Ελλάδα'), ltrim('Ελλάδα', 'ab'), hex('Ελλάδα'), quote('Ελλάδα'), unicode('Ελλάδα'), 'Ελλάδα' LIKE 'a%', 'Ελλάδα' GLOB '*', char(67, 457), 'Ελλάδα' || 'beta', 'Ελλάδα' < 'beta', 'Ελλάδα' = 'beta' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -2, 5), instr('it''s', '-7'), replace('it''s', 'é', 'XY'), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE 'A%', 'it''s' GLOB '?', char(69, 578), 'it''s' || '-7', 'it''s' < '-7', 'it''s' = '-7' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', -2, 0), instr('alpha', ''), replace('alpha', 'a', ''), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%a_', 'alpha' GLOB '*', char(83, 989), 'alpha' || '', 'alpha' < '', 'alpha' = '' COLLATE NOCASE;
SELECT length('café'), upper('café'), lower('café'), substr('café', -2, 2), instr('café', 'iota'), replace('café', 'é', 'XY'), trim('café'), ltrim('café', 'ab'), hex('café'), quote('café'), unicode('café'), 'café' LIKE '%é%', 'café' GLOB '*', char(90, 395), 'café' || 'iota', 'café' < 'iota', 'café' = 'iota' COLLATE NOCASE;
SELECT length('rho'), upper('rho'), lower('rho'), substr('rho', 0, 0), instr('rho', '0x1F'), replace('rho', 'e', ''), trim('rho'), ltrim('rho', 'ab'), hex('rho'), quote('rho'), unicode('rho'), 'rho' LIKE '%', 'rho' GLOB '*', char(72, 480), 'rho' || '0x1F', 'rho' < '0x1F', 'rho' = '0x1F' COLLATE NOCASE;
CREATE INDEX IF NOT EXISTS i67 ON t0(c2 DESC, id) WHERE c2 IS NOT NULL;
SELECT id, c2 FROM t0 WHERE c2 = -2 ORDER BY c2, id;
SELECT count(*) FROM t0 INDEXED BY i67 WHERE c2 IS NOT NULL;
REINDEX t0;
DROP INDEX IF EXISTS i67;
